## Frame-strip fixture for Effect B (CHANGE-BRIEF.md, Effect B "The frame strip"). Preview only:
## changes no game script. A standing YunqiZ drawn as tank.gd draws it (hull and turret sprites at
## scale 0.5, turret at TURRET_OFFSET, facing up_right as at the game's spawn, aim_angle -0.6) on
## the real ground tile, beside one real cover block (scripts/cover.gd, world = null, never hit).
## Camera at (640, 360), zoom 1. The smoke sits at TURRET_OFFSET, as tank.gd will place it, and is
## driven only through its follow(), the same mapping the tank will call.
## Frame numbers are Engine.get_frames_drawn(), which equals the Movie Maker frame number.

## [frame, health_ratio]: condition starts, heavier damage, condition ends (as on respawn).
const STEPS := [[10, 0.5], [60, 0.1], [110, 1.0]]

## Fixed seed for this preview's instance only; the effect scene never sets one.
@export var fixed_seed := 7

@onready var smoke: GPUParticles2D = $YunqiZ/Smoke

var _done := {}


func _ready() -> void:
	smoke.use_fixed_seed = true
	smoke.seed = fixed_seed


func _process(_delta: float) -> void:
	var f := Engine.get_frames_drawn()
	for step in STEPS:
		if f >= step[0] and not _done.has(step[0]):
			_done[step[0]] = true
			smoke.follow(step[1], false)
			print("preview: frame %d, h %.2f -> emitting %s, amount_ratio %.4f, amount %d" % [f, step[1], smoke.emitting, smoke.amount_ratio, smoke.amount])

func _shoot_when(ok: bool, gap_ticks: int) -> void:
	if fire_held and main.audio.count("fire") > int(last_counts.get("_fire_seen", 0)):
		last_counts["_fire_seen"] = main.audio.count("fire")
		last_shot_tick = tick
		_set_fire(false)
		return
	_set_fire(ok and tick - last_shot_tick >= gap_ticks)


func _set_fire(on: bool) -> void:
	if on and not fire_held:
		fire_held = true
		_press("fire")
	elif not on and fire_held:
		fire_held = false
		_release("fire")


func _warp_aim() -> void:
	var vp := get_viewport()
	vp.warp_mouse(vp.get_canvas_transform() * aim_world)


## Point the aim so the shell line (which starts at the muzzle) passes through `target`.
func _aim_at(target: Vector2) -> void:
	var p = main.player
	var ppos: Vector2 = p.global_position
	var pivot: Vector2 = ppos + TURRET_OFFSET
	var d: Vector2 = (target - ppos).normalized()
	for i in 4:
		var ground := Vector2(d.x, d.y / SIN_E).normalized()
		var muzzle: Vector2 = ppos + Vector2(ground.x, ground.y * SIN_E) * BARREL_LEN
		d = (target - muzzle).normalized()
	aim_world = pivot + d * 220.0


func _lead(e) -> Vector2:
	var p = main.player
	var t := 0.0
	var ppos: Vector2 = p.global_position

func _check_life(b: Dictionary) -> void:
	var secs := _secs(b.exit - b.frame)
	_check("burst %d (%s) freed itself %.3f s after it appeared (want %.2f-%.2f)" % [b.idx, b.phase, secs, LIFE_MIN, LIFE_MAX],
		b.exit >= 0 and secs >= LIFE_MIN and secs <= LIFE_MAX)


## Real mouse input: a motion event at the window point that shows `world_pos`.
## Window coordinates include the canvas_items stretch (the headless window is not 1280 x 720).
func _aim_at(world_pos: Vector2) -> void:
	var vp: Viewport = main.get_viewport()
	var screen: Vector2 = vp.get_final_transform() * (vp.get_canvas_transform() * world_pos)
	var ev := InputEventMouseMotion.new()
	ev.position = screen
	ev.global_position = screen
	Input.parse_input_event(ev)


func _key(code: Key, pressed: bool) -> void:
	var ev := InputEventKey.new()
	ev.keycode = code
	ev.physical_keycode = code
	ev.pressed = pressed
	Input.parse_input_event(ev)

extends "res://scripts/tank.gd"
## Enemy tank: wanders between random waypoints, turns its turret toward YunqiZ and fires when it
## has a clear line of sight. Uses the YunqiZ sprites tinted grey (code, not a separate asset).

var target = null
var arena := Rect2(90, 90, 1100, 540)
var _wp := Vector2.ZERO
var _wp_left := 0.0
var _rng := RandomNumberGenerator.new()


func _ready() -> void:
	super._ready()
	_rng.randomize()
	reload_left = _rng.randf_range(1.5, 3.0)


func _think(delta: float) -> void:
	if target == null or target.is_dead or world == null or world.level_won:
		move_dir = Vector2.ZERO
		return
	_wp_left -= delta
	if _wp_left <= 0.0 or global_position.distance_to(_wp) < 12.0:
		_wp = Vector2(_rng.randf_range(arena.position.x, arena.end.x), _rng.randf_range(arena.position.y, arena.end.y))
		_wp_left = _rng.randf_range(2.0, 4.0)
	var to_wp := _wp - global_position
	move_dir = to_wp.normalized() if to_wp.length() > 12.0 else Vector2.ZERO
	var to_target: Vector2 = target.global_position - global_position
	aim_angle = lerp_angle(aim_angle, to_target.angle(), clampf(delta * 3.0, 0.0, 1.0))
	var off := absf(wrapf(aim_angle - to_target.angle(), -PI, PI))
	if reload_left <= 0.0 and to_target.length() < 700.0 and off < 0.15 and _has_line_of_sight():
		if try_fire():
			reload_left = reload_time + _rng.randf_range(0.0, 1.0)


func _has_line_of_sight() -> bool:
	var q := PhysicsRayQueryParameters2D.create(global_position, target.global_position, 1 | 2, [get_rid()])
	var hit := get_world_2d().direct_space_state.intersect_ray(q)
	return not hit.is_empty() and hit.collider == target


func _play_fire_sound() -> void:
	world.audio.play("fire", -6.0, 0.85, "enemy_fire")


func _play_hit_sound() -> void:
	world.audio.play("player_hit", -8.0, 0.8, "enemy_hit")

